// Optimización de imágenes servidas desde Cloudinary: inserta f_auto (WebP/AVIF
// según el navegador), q_auto y un ancho máximo. Las URLs que no son de
// Cloudinary y las transformaciones firmadas se devuelven tal cual.
const CLOUDINARY = /^(https?:\/\/res\.cloudinary\.com\/[^/]+\/image\/upload\/)(.+)$/

export function isCloudinary(url) {
  return typeof url === 'string' && CLOUDINARY.test(url)
}

export function optimizeImage(url, width) {
  if (typeof url !== 'string') return url
  const m = url.match(CLOUDINARY)
  if (!m) return url
  // Signed transformations must be regenerated by the owner, never invalidated.
  if (m[2].startsWith('s--')) return url
  const size = Number.isFinite(Number(width)) ? Math.max(64,Math.min(2560,Math.round(Number(width)))) : 800
  const parts=m[2].split('/'),transforms=[]
  while (/^(?:(?:a|ac|ar|b|bo|c|co|d|dn|dpr|e|f|fl|g|h|l|o|pg|q|r|t|u|w|x|y|z)_)/.test(parts[0])) transforms.push(parts.shift())
  const existing=transforms.flatMap(part=>part.split(',')).filter(part=>!/^([fqw])_/.test(part))
  return `${m[1]}${[...existing,'f_auto','q_auto',...(existing.some(part=>part.startsWith('c_'))?[]:['c_limit']),`w_${size}`].join(',')}/${parts.join('/')}`
}

// srcset solo si es Cloudinary (en otro host no hay forma de pedir otro tamaño).
export function imageSrcSet(url, widths) {
  if (!isCloudinary(url)) return undefined
  return widths.map((w) => `${optimizeImage(url, w)} ${w}w`).join(', ')
}
